import { TaskStatus, type TaskRepeat, type WorkTask } from "../../types/work-projects"

/*
 * Project extras: tasks that come back, the deleted tasks bin and done tasks
 * that leave the board after a while.
 */

/** Days a deleted task can be brought back. */
export const TASK_BIN_DAYS = 30
/** Done tasks leave the board and list this many days after they were finished. */
export const ARCHIVE_AFTER_DAYS = 30

const DAY = 86_400_000
const toDay = (d: Date) => d.toISOString().slice(0, 10)

/** yyyy-mm-dd moved on by the repeat; months keep the day, or the month's last day. */
export function addRepeat(date: string, repeat: Pick<TaskRepeat, "every" | "interval">): string {
  const d = new Date(`${date}T00:00:00Z`)
  const n = Math.max(1, Math.floor(repeat.interval))
  if (repeat.every === "day") return toDay(new Date(d.getTime() + n * DAY))
  if (repeat.every === "week") return toDay(new Date(d.getTime() + n * 7 * DAY))
  const day = d.getUTCDate()
  const first = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + n, 1))
  const last = new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth() + 1, 0)).getUTCDate()
  return toDay(new Date(Date.UTC(first.getUTCFullYear(), first.getUTCMonth(), Math.min(day, last))))
}

/** Throws the first problem with a repeat. */
export function assertRepeat(repeat: TaskRepeat | undefined) {
  if (!repeat) return
  if (!["day", "week", "month"].includes(repeat.every)) throw new Error("Choose how often the task comes back")
  if (!(Number.isInteger(repeat.interval) && repeat.interval >= 1 && repeat.interval <= 12)) throw new Error("A task can come back every 1 to 12 days, weeks or months")
}

/**
 * The dates of the next task when a repeating one is done: from its due date
 * (or the day it was done when it had none), the start date keeping its gap.
 * Null once past the repeat's end.
 */
export function nextDates(task: Pick<WorkTask, "repeat" | "dueDate" | "startDate">, doneOn: string): { dueDate: string; startDate?: string } | null {
  if (!task.repeat) return null
  const base = task.dueDate ?? doneOn
  let dueDate = addRepeat(base, task.repeat)
  // a task finished late doesn't come back already late
  while (dueDate < doneOn) dueDate = addRepeat(dueDate, task.repeat)
  if (task.repeat.until && dueDate > task.repeat.until) return null
  const gap = task.startDate && task.dueDate ? Math.round((Date.parse(task.dueDate) - Date.parse(task.startDate)) / DAY) : undefined
  return { dueDate, ...(gap !== undefined ? { startDate: toDay(new Date(Date.parse(`${dueDate}T00:00:00Z`) - gap * DAY)) } : {}) }
}

/** A task done more than ARCHIVE_AFTER_DAYS ago leaves the board and list (it still counts in progress). */
export function isArchived(task: Pick<WorkTask, "status" | "completedAt">, today: string, days = ARCHIVE_AFTER_DAYS) {
  if (days <= 0 || task.status !== TaskStatus.DONE || !task.completedAt) return false
  return Date.parse(`${today}T00:00:00Z`) - Date.parse(task.completedAt) > days * DAY
}

/** Whole days left before a deleted task is removed for good. */
export function taskBinDaysLeft(deletedAt: string, now = new Date()) {
  return Math.max(0, TASK_BIN_DAYS - Math.floor((now.getTime() - Date.parse(deletedAt)) / DAY))
}
